def is_nested(string):
    stack = []
    nested_found = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if len(stack) > 0:  # If there are still brackets in the stack, we have nested brackets
                    nested_found = True
            else:
                return False  # Unmatched closing bracket

    return nested_found and len(stack) == 0  # Must be nested and all brackets must be matched

